let _Vendor = dynamic([{Vendor}]);
let _Firewall = dynamic([{Firewall}]);
let _SourceIP = dynamic([{SourceIP}]);
let _DestIP = dynamic([{DestinationIP}]);
let _Action = dynamic([{Action}]);
let _Severity = dynamic([{Severity}]);
let _Protocol = dynamic([{Protocol}]);
let _App = dynamic([{Application}]);
let _Country = dynamic([{Country}]);
let FW = CommonSecurityLog
| where TimeGenerated {TimeRange}
| where array_length(_Vendor) == 0 or DeviceVendor in~ (_Vendor)
| where array_length(_Firewall) == 0 or DeviceName in~ (_Firewall)
| where array_length(_SourceIP) == 0 or SourceIP in~ (_SourceIP)
| where array_length(_DestIP) == 0 or DestinationIP in~ (_DestIP)
| where array_length(_Action) == 0 or tolower(tostring(column_ifexists("DeviceAction", "unknown"))) in~ (_Action)
| where array_length(_Severity) == 0 or tolower(tostring(coalesce(column_ifexists("Severity", ""), column_ifexists("LogSeverity", ""), "unknown"))) in~ (_Severity)
| where array_length(_Protocol) == 0 or tolower(tostring(column_ifexists("Protocol", "unknown"))) in~ (_Protocol)
| where array_length(_App) == 0 or tolower(coalesce(tostring(column_ifexists("ApplicationProtocol", "")), tostring(column_ifexists("Application", "")), "unknown")) in~ (_App)
| where array_length(_Country) == 0 or tolower(tostring(geo_info_from_ip_address(SourceIP).country)) in~ (_Country) or tolower(tostring(geo_info_from_ip_address(DestinationIP).country)) in~ (_Country)
| extend Act = tolower(tostring(column_ifexists("DeviceAction", "unknown")));
let Sessions = toscalar(FW | count);
let Allowed = toscalar(FW | where Act in ('allow','accept','permit','allowed') | count);
let Denied = toscalar(FW | where Act in ('deny','drop','reject','blocked','discard','denied','reset-both','reset-client','reset-server') | count);
let GB = toscalar(FW | summarize round(sum(tolong(column_ifexists("SentBytes", 0)) + tolong(column_ifexists("ReceivedBytes", 0))) / 1000000000.0, 2));
let IPS = toscalar(FW | where tolower(tostring(column_ifexists('DeviceEventClassID',''))) has_any ('ips','ids','signature','anomaly') or tolower(tostring(column_ifexists('Activity',''))) has_any ('ips','ids','intrusion','signature','exploit') | count);
let Malware = toscalar(FW | where tolower(tostring(column_ifexists('Message',''))) has_any ('malware','virus','trojan','ransom','worm','spyware','botnet') or tolower(tostring(column_ifexists('Activity',''))) has_any ('virus','malware','antivirus','wildfire','spyware') | count);
let TIHits = toscalar(FW | where isnotempty(tostring(column_ifexists('MaliciousIP',''))) | count);
let CritHigh = toscalar(FW | where tolower(tostring(coalesce(column_ifexists('Severity',''), column_ifexists('LogSeverity',''), ''))) in ('high','critical','very-high','7','8','9','10','1','2') | count);
let Firewalls = toscalar(FW | summarize dcount(DeviceName));
let Silent = toscalar(FW | summarize LastSeen = max(TimeGenerated) by DeviceName | where datetime_diff('minute', now(), LastSeen) > 30 | count);
union
(print Order=1, Metric='Sessions', Value=toreal(Sessions)),
(print Order=2, Metric='Allowed', Value=toreal(Allowed)),
(print Order=3, Metric='Denied', Value=toreal(Denied)),
(print Order=4, Metric='Traffic (GB)', Value=toreal(GB)),
(print Order=5, Metric='IPS / IDS', Value=toreal(IPS)),
(print Order=6, Metric='Malware', Value=toreal(Malware)),
(print Order=7, Metric='TI hits', Value=toreal(TIHits)),
(print Order=8, Metric='Critical / High', Value=toreal(CritHigh)),
(print Order=9, Metric='Firewalls reporting', Value=toreal(Firewalls)),
(print Order=10, Metric='Firewalls silent (>30m)', Value=toreal(Silent))
| order by Order asc
| project Metric, Value

